import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 mihomo、sing-box、Surge、Quantumult X、Shadowrocket、Stash、Loon 的兼容性","description":"汇总 Clash 与 mihomo、sing-box、Surge、Quantumult X、Shadowrocket 小火箭、Stash 和 Loon 的配置、订阅、节点迁移方式与协议兼容性。","frontmatter":{"title":"Clash 与 mihomo、sing-box、Surge、Quantumult X、Shadowrocket、Stash、Loon 的兼容性","description":"汇总 Clash 与 mihomo、sing-box、Surge、Quantumult X、Shadowrocket 小火箭、Stash 和 Loon 的配置、订阅、节点迁移方式与协议兼容性。","head":[["meta",{"name":"keywords","content":"Clash iOS兼容,mihomo iOS,sing-box节点,Surge节点,Quantumult X节点,Shadowrocket小火箭订阅,Stash订阅,Loon订阅,Clash YAML,代理分享链接"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"如何把 sing-box 节点迁移到 Clash？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"优先使用服务商提供的 mihomo YAML 订阅，也可以根据协议与参数在 Clash 节点编辑器中重新添加。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"如何迁移 Surge 或 Quantumult X 节点？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"使用返回 mihomo YAML 的订阅，或在节点编辑器中按原服务器与协议参数添加节点。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Shadowrocket 小火箭的订阅可以用于 Clash 吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"服务商能够通过 HTTPS 订阅地址返回 mihomo YAML 时即可使用；规则与模块可以用 Clash 的规则和对应功能重新建立。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"如何使用 ss:// 或 Base64 节点列表？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以先整理为 mihomo YAML，或根据其中的服务器、端口、凭据和协议参数在 Clash 节点编辑器中添加。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility.md","filePath":"zh/guide/compatibility.md","lastUpdated":1785318168000}`),a={name:`zh/guide/compatibility.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与常见代理软件的兼容性" tabindex="-1">Clash 与常见代理软件的兼容性 <a class="header-anchor" href="#clash-与常见代理软件的兼容性" aria-label="Permalink to “Clash 与常见代理软件的兼容性”">​</a></h1><p><strong>先说结论：</strong> Clash 可以直接读取 mihomo 格式的 YAML 配置，以及返回 mihomo YAML 的 HTTPS 订阅，也能读取 Stash 使用的标准 Clash / mihomo YAML。来自 sing-box、Surge、Quantumult X、Shadowrocket 或 Loon 的服务器和节点，可以通过兼容订阅或按参数添加继续使用。</p><h2 id="按你现在使用的软件查看" tabindex="-1">按你现在使用的软件查看 <a class="header-anchor" href="#按你现在使用的软件查看" aria-label="Permalink to “按你现在使用的软件查看”">​</a></h2><table tabindex="0"><thead><tr><th>你现在使用的软件</th><th>推荐的配置方式</th><th>节点使用方式</th><th>详细说明</th></tr></thead><tbody><tr><td>Clash / mihomo</td><td>直接使用标准 mihomo YAML</td><td>直接使用</td><td><a href="/clash.md/zh/guide/compatibility/mihomo">mihomo 兼容说明</a></td></tr><tr><td>sing-box</td><td>获取 mihomo 订阅或整理为 YAML</td><td>按支持的协议参数添加</td><td><a href="/clash.md/zh/guide/compatibility/sing-box">sing-box 兼容说明</a></td></tr><tr><td>Surge</td><td>获取 mihomo 订阅或重建节点</td><td>支持 Snell 等共同协议</td><td><a href="/clash.md/zh/guide/compatibility/surge">Surge 兼容说明</a></td></tr><tr><td>Quantumult X</td><td>使用 mihomo 订阅</td><td>也可按参数添加</td><td><a href="/clash.md/zh/guide/compatibility/quantumult-x">Quantumult X 兼容说明</a></td></tr><tr><td>Shadowrocket（小火箭）</td><td>使用 mihomo 订阅</td><td>也可按参数添加</td><td><a href="/clash.md/zh/guide/compatibility/shadowrocket">Shadowrocket 兼容说明</a></td></tr><tr><td>Stash</td><td>直接使用标准 Clash / mihomo YAML</td><td>直接使用</td><td><a href="/clash.md/zh/guide/compatibility/stash">Stash 兼容说明</a></td></tr><tr><td>Loon</td><td>使用 mihomo 订阅</td><td>也可按参数添加</td><td><a href="/clash.md/zh/guide/compatibility/loon">Loon 兼容说明</a></td></tr></tbody></table><h2 id="兼容-分为三层" tabindex="-1">“兼容”分为三层 <a class="header-anchor" href="#兼容-分为三层" aria-label="Permalink to ““兼容”分为三层”">​</a></h2><ol><li><strong>配置格式兼容</strong>：整个配置文件的直接复用方式。</li><li><strong>订阅格式兼容</strong>：通过 HTTPS 订阅获取 Clash 可直接读取的 mihomo YAML。</li><li><strong>协议互通</strong>：使用同一台服务器直接连接。</li></ol><p>Clash 在订阅格式与协议互通层覆盖广泛。产品专用设置可以用 mihomo YAML、 Clash 规则与对应功能重新建立。</p><h2 id="clash-可以直接导入什么" tabindex="-1">Clash 可以直接导入什么？ <a class="header-anchor" href="#clash-可以直接导入什么" aria-label="Permalink to “Clash 可以直接导入什么？”">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>结果</th></tr></thead><tbody><tr><td>mihomo YAML 配置</td><td>直接导入</td></tr><tr><td>返回 mihomo YAML 的订阅</td><td>直接添加 URL；可切换订阅 User-Agent</td></tr><tr><td><code>ss://</code> 等单节点分享链接</td><td>转换成 mihomo YAML，或根据参数在节点编辑器添加</td></tr><tr><td>Base64 节点列表</td><td>整理为 mihomo YAML 后导入</td></tr><tr><td>包含 HTTPS 订阅地址的二维码</td><td>扫码添加远程配置</td></tr></tbody></table><p>完整范围请参阅<a href="/clash.md/zh/guide/protocols">支持的协议</a>。</p><h2 id="常见问答" tabindex="-1">常见问答 <a class="header-anchor" href="#常见问答" aria-label="Permalink to “常见问答”">​</a></h2><h3 id="shadowrocket-小火箭的订阅可以继续使用吗" tabindex="-1">Shadowrocket 小火箭的订阅可以继续使用吗？ <a class="header-anchor" href="#shadowrocket-小火箭的订阅可以继续使用吗" aria-label="Permalink to “Shadowrocket 小火箭的订阅可以继续使用吗？”">​</a></h3><p>服务商能够通过该 HTTPS 订阅地址返回 mihomo 兼容 YAML 时即可使用。小火箭的规则、模块和 App 设置可以用 Clash 的规则与对应功能重新建立，具体请看 <a href="/clash.md/zh/guide/compatibility/shadowrocket">Shadowrocket 兼容说明</a>。</p><h3 id="原来的机场或服务商订阅可以继续使用吗" tabindex="-1">原来的机场或服务商订阅可以继续使用吗？ <a class="header-anchor" href="#原来的机场或服务商订阅可以继续使用吗" aria-label="Permalink to “原来的机场或服务商订阅可以继续使用吗？”">​</a></h3><p>只要服务商能够返回 mihomo 兼容 YAML，就可以。Clash 允许切换订阅 User-Agent，适配按客户端名称选择输出格式的面板。</p><h3 id="可以继续使用同一台服务器吗" tabindex="-1">可以继续使用同一台服务器吗？ <a class="header-anchor" href="#可以继续使用同一台服务器吗" aria-label="Permalink to “可以继续使用同一台服务器吗？”">​</a></h3><p>只要协议和全部必要参数都受支持，同一台服务器即可直接使用。</p><h3 id="提到这些品牌是否代表存在合作关系" tabindex="-1">提到这些品牌是否代表存在合作关系？ <a class="header-anchor" href="#提到这些品牌是否代表存在合作关系" aria-label="Permalink to “提到这些品牌是否代表存在合作关系？”">​</a></h3><p>这些品牌名称仅用于说明配置与协议兼容性。Clash 与 Hako 由独立团队开发和维护。</p>`,19)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};